import{_ as e,o as i,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"UC 01 — Authentication & Profile (UC-01 → UC-12)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/01-authentication-profile.md","filePath":"ba/use-cases/01-authentication-profile.md"}'),l={name:"ba/use-cases/01-authentication-profile.md"};function n(s,t,a,d,c,g){return i(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="uc-01-—-authentication-profile-uc-01-→-uc-12" tabindex="-1">UC 01 — Authentication &amp; Profile (UC-01 → UC-12) <a class="header-anchor" href="#uc-01-—-authentication-profile-uc-01-→-uc-12" aria-label="Permalink to &quot;UC 01 — Authentication &amp; Profile (UC-01 → UC-12)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../02-authentication-profile.html">02-authentication-profile.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code></p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-01</td><td>Sign Up</td><td>GUEST</td><td>3.2.1, 3.2.6</td></tr><tr><td>UC-02</td><td>Sign In with Email</td><td>GUEST</td><td>3.2.2</td></tr><tr><td>UC-03</td><td>Sign In with Google OAuth</td><td>GUEST</td><td>3.2.3</td></tr><tr><td>UC-04</td><td>Forgot &amp; Reset Password</td><td>GUEST/USER</td><td>3.2.4</td></tr><tr><td>UC-05</td><td>Change Password</td><td>USER</td><td>3.2.5</td></tr><tr><td>UC-06</td><td>Enable/Disable Two-Factor Authentication (2FA)</td><td>USER</td><td>3.2.7</td></tr><tr><td>UC-07</td><td>Sign Out</td><td>USER</td><td>3.2.8</td></tr><tr><td>UC-08</td><td>Deactivate Account</td><td>USER</td><td>3.2.9</td></tr><tr><td>UC-09</td><td>View Personal Profile</td><td>USER</td><td>3.3.1</td></tr><tr><td>UC-10</td><td>Update Personal Profile</td><td>USER</td><td>3.3.2</td></tr><tr><td>UC-11</td><td>View Client Profile</td><td>USER (Client)</td><td>3.3.3</td></tr><tr><td>UC-12</td><td>Update Client Profile</td><td>USER (Client)</td><td>3.3.4</td></tr></tbody></table><hr><h2 id="uc-01-—-sign-up" tabindex="-1">UC-01 — Sign Up <a class="header-anchor" href="#uc-01-—-sign-up" aria-label="Permalink to &quot;UC-01 — Sign Up&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> GUEST</li><li><strong>Description:</strong> User registers a new account with email; system sends an OTP to verify the email is real.</li><li><strong>Precondition:</strong> User is not authenticated. Email not already registered.</li><li><strong>Main Flow:</strong><ol><li>GUEST opens Sign Up screen, enters email, password, full name.</li><li>System normalizes email local-part case (<code>User@gmail.com</code> ≡ <code>user@gmail.com</code>) and checks for existing account.</li><li>System creates account in <code>PENDING_VERIFICATION</code> state, sends OTP to email.</li><li>User enters OTP on verification screen (UC shared with Reset Password, 2FA — see FR 3.2.6).</li><li>System verifies OTP, activates account, redirects to Sign In.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Email already registered (case-insensitive local-part match) → reject with duplicate-account error.</li><li>A2. OTP incorrect or expired → allow resend, max retry limit applies.</li></ul></li><li><strong>Postcondition:</strong> Active user account created.</li></ul><h2 id="uc-02-—-sign-in-with-email" tabindex="-1">UC-02 — Sign In with Email <a class="header-anchor" href="#uc-02-—-sign-in-with-email" aria-label="Permalink to &quot;UC-02 — Sign In with Email&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> GUEST</li><li><strong>Description:</strong> Sign in directly with registered email/password, no OTP required.</li><li><strong>Precondition:</strong> Account exists and is verified/active.</li><li><strong>Main Flow:</strong><ol><li>GUEST enters email + password.</li><li>System validates credentials, issues session/JWT.</li><li>Redirect to last-used context (Agency list or Dashboard).</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Wrong password → error, no OTP triggered (differs from Sign Up).</li><li>A2. Account deactivated → block login, show reactivation guidance.</li><li>A3. 2FA enabled (FR 3.2.7) → require OTP/TOTP step before session issued.</li></ul></li></ul><h2 id="uc-03-—-sign-in-with-google-oauth" tabindex="-1">UC-03 — Sign In with Google OAuth <a class="header-anchor" href="#uc-03-—-sign-in-with-google-oauth" aria-label="Permalink to &quot;UC-03 — Sign In with Google OAuth&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> GUEST</li><li><strong>Description:</strong> Quick sign-in via a Google account.</li><li><strong>Precondition:</strong> None.</li><li><strong>Main Flow:</strong><ol><li>GUEST clicks &quot;Sign in with Google&quot;.</li><li>Redirect to Google OAuth consent screen.</li><li>On success, system matches/creates account by verified Google email, issues session.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Google email matches an existing email/password account → link accounts (or block, per final decision — <strong>[OPEN QUESTION]</strong>, flow currently broken per <code>docs/ba/02</code> note).</li></ul></li><li><strong>Note:</strong> Current implementation reported non-functional — treat as bug-fix-on-existing-flow, not pure new feature.</li></ul><h2 id="uc-04-—-forgot-reset-password" tabindex="-1">UC-04 — Forgot &amp; Reset Password <a class="header-anchor" href="#uc-04-—-forgot-reset-password" aria-label="Permalink to &quot;UC-04 — Forgot &amp; Reset Password&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> GUEST/USER</li><li><strong>Description:</strong> Send a reset link or OTP for the user to confirm and set a new password when forgotten.</li><li><strong>Precondition:</strong> Account exists.</li><li><strong>Main Flow:</strong><ol><li>User requests password reset by email.</li><li>System sends reset link or OTP.</li><li>User confirms via link/OTP, enters new password.</li><li>System updates password, invalidates old sessions.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Email not registered → generic success message (no account enumeration).</li><li>A2. Reset link/OTP expired → user must request again.</li></ul></li></ul><h2 id="uc-05-—-change-password" tabindex="-1">UC-05 — Change Password <a class="header-anchor" href="#uc-05-—-change-password" aria-label="Permalink to &quot;UC-05 — Change Password&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> Change the current password, requiring re-confirmation before saving.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>User enters current password + new password (typed twice, or confirm modal).</li><li>System validates current password.</li><li>System saves new password hash, invalidates other active sessions.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Current password incorrect → reject.</li><li>A2. New password fails confirm-match → reject before submit.</li></ul></li></ul><h2 id="uc-06-—-enable-disable-two-factor-authentication-2fa" tabindex="-1">UC-06 — Enable/Disable Two-Factor Authentication (2FA) <a class="header-anchor" href="#uc-06-—-enable-disable-two-factor-authentication-2fa" aria-label="Permalink to &quot;UC-06 — Enable/Disable Two-Factor Authentication (2FA)&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> Enable or disable 2FA via QR scan (TOTP) or OTP code.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>User opens Security settings, selects Enable 2FA.</li><li>System shows QR code for Authenticator app scan.</li><li>User enters generated TOTP code to confirm.</li><li>System enables 2FA flag on account.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Disable 2FA → require current password/OTP re-confirm before turning off.</li></ul></li><li><strong>Note:</strong> Backup codes and secret-key copy removed from scope (simplified for reduced attack surface).</li></ul><h2 id="uc-07-—-sign-out" tabindex="-1">UC-07 — Sign Out <a class="header-anchor" href="#uc-07-—-sign-out" aria-label="Permalink to &quot;UC-07 — Sign Out&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> Sign out of the system, saving the last-used platform for easier future sign-in.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>User triggers Sign Out.</li><li>System invalidates current session/refresh token.</li><li>System persists &quot;last used login platform&quot; (email vs Google OAuth) for next login UX.</li></ol></li></ul><h2 id="uc-08-—-deactivate-account" tabindex="-1">UC-08 — Deactivate Account <a class="header-anchor" href="#uc-08-—-deactivate-account" aria-label="Permalink to &quot;UC-08 — Deactivate Account&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> Soft-delete the user&#39;s account upon request.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>User requests account deactivation, confirms via modal.</li><li>System marks account <code>INACTIVE</code>/soft-deleted, invalidates sessions.</li></ol></li><li><strong>Postcondition:</strong> Account inactive, data retained (soft delete).</li></ul><h2 id="uc-09-—-view-personal-profile" tabindex="-1">UC-09 — View Personal Profile <a class="header-anchor" href="#uc-09-—-view-personal-profile" aria-label="Permalink to &quot;UC-09 — View Personal Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> View the user&#39;s personal profile information.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>User opens Profile screen.</li><li>System displays profile fields (full name, email, avatar, etc.).</li></ol></li><li><strong>Note:</strong> Exact field list is an <strong>[OPEN QUESTION]</strong> pending DB schema design (see <code>docs/ba/02</code> §3.3.1).</li></ul><h2 id="uc-10-—-update-personal-profile" tabindex="-1">UC-10 — Update Personal Profile <a class="header-anchor" href="#uc-10-—-update-personal-profile" aria-label="Permalink to &quot;UC-10 — Update Personal Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER</li><li><strong>Description:</strong> Update the user&#39;s personal profile information.</li><li><strong>Precondition:</strong> User authenticated.</li><li><strong>Main Flow:</strong><ol><li>User edits profile fields, submits.</li><li>System validates and persists changes.</li></ol></li><li><strong>Note:</strong> View and Update are a single combined FR (3.3.2) per BA decision — not separated at the FR-naming level.</li></ul><h2 id="uc-11-—-view-client-profile" tabindex="-1">UC-11 — View Client Profile <a class="header-anchor" href="#uc-11-—-view-client-profile" aria-label="Permalink to &quot;UC-11 — View Client Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER (Client)</li><li><strong>Description:</strong> View the dedicated profile used when joining a workspace in the Client role.</li><li><strong>Precondition:</strong> User has been added to at least one Workspace as CLIENT.</li><li><strong>Main Flow:</strong><ol><li>Client opens Client Profile screen (separate from personal User Profile).</li><li>System displays Client Profile fields, reused across any Agency/Workspace the same email joins.</li></ol></li><li><strong>Business Rule:</strong> Client Profile is agency-independent — same profile reused across multiple Agencies/Workspaces (see <a href="./../01-organization-structure.html">01-organization-structure.md</a> §5).</li></ul><h2 id="uc-12-—-update-client-profile" tabindex="-1">UC-12 — Update Client Profile <a class="header-anchor" href="#uc-12-—-update-client-profile" aria-label="Permalink to &quot;UC-12 — Update Client Profile&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> USER (Client)</li><li><strong>Description:</strong> Update the Client profile (email field cannot be edited).</li><li><strong>Precondition:</strong> User has a Client Profile.</li><li><strong>Main Flow:</strong><ol><li>Client edits allowed fields (name, contact phone, etc.).</li><li>System rejects any attempt to change email (email is the cross-Agency identity key).</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Attempt to edit email field → blocked/read-only at UI and API level.</li></ul></li></ul>',29)])])}const p=e(l,[["render",n]]);export{h as __pageData,p as default};
